	q := []int{}
	for i, d := range indeg {
		if d == 0 {
			q = append(q, i)
		}
	}
	taken := 0
	for len(q) > 0 { // Kahn's algorithm: a cycle leaves courses with indegree > 0
		u := q[0]
		q = q[1:]
		taken++
		for _, v := range g[u] {
			if indeg[v]--; indeg[v] == 0 {
				q = append(q, v)
			}
		}
	}
	return taken == numCourses
}

