		q = q[1:]
		if p[0] == n-1 && p[1] == n-1 {
			return p[2]
		}
		for dr := -1; dr <= 1; dr++ { // 8 directions
			for dc := -1; dc <= 1; dc++ {
				nr, nc := p[0]+dr, p[1]+dc
				if nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 0 {
					grid[nr][nc] = 1
					q = append(q, [3]int{nr, nc, p[2] + 1})
				}
			}
		}
	}
	return -1
}

