class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)

        def cell(s):
            r, c = divmod(s - 1, n)
            if r % 2:
                c = n - 1 - c
            return board[n - 1 - r][c]

        q, seen, moves = deque([1]), {1}, 0
        while q:
            for _ in range(len(q)):
                s = q.popleft()
                if s == n * n:
                    return moves
                for nxt in range(s + 1, min(s + 6, n * n) + 1):
                    dest = cell(nxt) if cell(nxt) != -1 else nxt
                    if dest not in seen:
                        seen.add(dest)
                        q.append(dest)
            moves += 1
        return -1

